// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Trigger').first().json.contact_id || '').trim();
const ok = /^(tg:\d{1,20}|wa:\+\d{1,20})$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];

// Two texts. `text` is the owner message: contact first, then name, reason, status, then as much history as fits. `flagFailureText` is only sent if the flag fails AFTER the owner was told.
// The contact, the reason and the history are client- or agent-controlled: each is cleaned before it is interpolated, and the header is built first so a long history can only use what is left of the budget.
const MAX = 3500; // Telegram allows 4096; notify_owner cuts at 4000 BEFORE escaping, so no < > & may reach it (they are replaced below)
const ID_RE = /^(tg:\d{1,20}|wa:\+\d{1,20})$/;
const clean = (s, max) => {
  // cut BEFORE expanding (a jsonb row can be megabytes), and drop a surrogate pair the cut may have split
  const t = String(s ?? '').slice(0, max * 4).replace(/[\ud800-\udbff]$/, '')
    .replace(/[\u0000-\u001f\u007f-\u009f\u061c\u200b-\u200f\u2028-\u202e\u2066-\u2069\ufeff]/g, ' ')
    .replace(/[<>&]/g, c => ({ '<': '\u2039', '>': '\u203a', '&': '\uff06' }[c])).replace(/\s+/g, ' ').trim();
  const a = Array.from(t);
  return a.length > max ? a.slice(0, max - 1).join('') + '\u2026' : t;
};
const inp = $('Trigger').first().json;
const contact = String(inp.contact_id ?? '').trim();
const contactOk = ID_RE.test(contact);
const client = $('Client').first().json || {};
const who = contactOk ? contact : (clean(contact, 40) || 'none') + ' [INVALID contact_id]';
const state = client.error ? 'client lookup FAILED - nothing was flagged; if this contact is a client, set the status to escalated by hand'
  : !client.id ? 'contact not on file - nothing to flag'
  : 'client on file - being set to escalated (you get a second message if that fails)';
const name = client.error ? '(unknown)' : !client.id ? '(not on file)' : (clean((client.fields || {}).name, 60) || 'unnamed client');
const head = `\ud83d\udea8 Escalation \u2014 ${who}\nName: ${name}\nReason: ${clean(inp.reason, 500) || '(none given)'}\nStatus: ${state}\n---`;
// History rows arrive newest first. Three different empty states: query failed (the node emits one item with .error, whose .message is the ERROR TEXT), no rows at all (the {} item of alwaysOutputData), rows that could not be read.
const items = $input.all().map(i => (i.json && typeof i.json === 'object') ? i.json : {});
const failed = items.some(r => r.error);
const rows = items.filter(r => !r.error && 'message' in r);
const textOf = c => typeof c === 'string' ? c : Array.isArray(c) ? c.slice(0, 20).map(p => typeof p === 'string' ? p : (p && p.type === 'text' && typeof p.text === 'string' ? p.text : '')).join(' ') : '';
const lines = [];
for (const r of rows) {
  try {
    let m = r.message;
    if (typeof m === 'string') m = JSON.parse(m);
    if (!m || typeof m !== 'object') continue;
    const speaker = m.type === 'human' ? 'Client' : m.type === 'ai' ? 'Bot' : null;
    if (!speaker) continue;
    const body = clean(textOf(m.data && m.data.content !== undefined ? m.data.content : m.content), 300);
    if (body) lines.push(`${speaker}: ${body}`);
  } catch (e) { /* skip */ }
}
const room = MAX - head.length - 1 - 45; // 45 = room for the "earlier messages not shown" line
const kept = [];
let used = 0;
for (const l of lines) { if (used + l.length + 1 > room) break; kept.push(l); used += l.length + 1; }
const omitted = lines.length - kept.length;
const body = kept.length
  ? (omitted ? `(${omitted} earlier message${omitted > 1 ? 's' : ''} not shown)\n` : '') + kept.reverse().join('\n')
  : !contactOk ? '(history not looked up: invalid contact_id)'
  : failed ? '(conversation history unavailable)'
  : rows.length ? `(history rows present but unreadable: ${rows.length})`
  : '(no conversation history yet)';
const flagFailureText = `\u26a0\ufe0f Escalation follow-up: ${who} (Clients row ${clean(client.id, 30)}) was reported to you, but its status could NOT be set to escalated. Set Clients.status = escalated by hand. Reason given: ${clean(inp.reason, 120) || '(none)'}`;
return [{ json: { text: head + '\n' + body, flagFailureText } }];
